mapper.select:
SELECT primary_key, enterprise_code, invoice_order_number, receiver_name,consignee_name,
sender_time, sender,logistics_number, logistics_info,
logistics_status, invoice_order_title,package_info,temp_detail,user_codes,packaged, business_belong
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'

    AND invoice_order_number LIKE '%'|| #{invoiceOrderNumber} ||'%'


    AND receiver_name LIKE '%'|| #{receiverName} ||'%'


    AND consignee_name LIKE '%'|| #{consigneeName} ||'%'


    AND sender IN

        #{userCode}



    AND sender_time >= #{senderTimePreDate}


    AND sender_time <= #{senderTimePostDate}


    ${dataScopeParams.dataScope}


    AND business_belong = #{businessBelong}


    AND logistics_number LIKE '%'|| #{logisticsNumber} ||'%'

ORDER BY id DESC

SELECT primary_key, enterprise_code, invoice_order_number, receiver_name,consignee_name,
sender_time, sender,logistics_number, logistics_info,
logistics_status, invoice_order_title,package_info,temp_detail,user_codes,packaged, business_belong
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'
AND primary_key= #{invoiceOrderCode}

    ${dataScopeParams.dataScope}

mapper.update:
UPDATE ${tableName}
SET temp_detail = NULL
WHERE enterprise_code = #{model.enterpriseCode}
  AND primary_key = #{model.invoiceOrderCode}
  AND temp_detail IS NOT NULL

UPDATE ${tableName}
SET temp_detail = #{model.tempDetail}
WHERE enterprise_code = #{model.enterpriseCode}
  AND primary_key = #{model.invoiceOrderCode}

UPDATE ${tableName}
SET invoice_order_number = #{model.invoiceOrderNumber},
    invoice_order_title  = #{model.invoiceOrderTitle},
    package_info         = #{model.packageInfo},
    packaged = #{model.packaged},
    temp_detail          = NULL
WHERE enterprise_code = #{model.enterpriseCode}
  AND primary_key = #{model.invoiceOrderCode}

