SELECT COUNT(id)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND primary_key != #{excludeInvoiceOrderCode}
  AND invoice_order_number = #{invoiceOrderNumber}
  AND delete_flag = 'f'
